#!/usr/bin/env node
// Generates supabase/tests/database/27_recurring_schedule_mirror.test.sql from
// supabase/tests/fixtures/recurring-schedule-cases.json -- the single fixture
// that proves src/engine/recurring (Jest) and the SQL mirror (plan 02-08,
// 20260926000300_recurring_series.sql: recurring_occurrence_date(),
// recurring_horizon()) agree on every case (D-04).
//
// Default mode: (re)writes the generated file.
// --check mode: regenerates in memory and exits 1 with a diff-style message
// if the file on disk differs -- used by CI to catch drift between the
// fixture and the checked-in generated file.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');
const FIXTURE_PATH = join(ROOT, 'supabase/tests/fixtures/recurring-schedule-cases.json');
const OUTPUT_PATH = join(ROOT, 'supabase/tests/database/27_recurring_schedule_mirror.test.sql');

// pgTAP test names are single-quoted SQL string literals; escape any single
// quote in a fixture's case name by doubling it, the standard SQL escape.
function sqlLiteral(s) {
  return `'${String(s).replace(/'/g, "''")}'`;
}

function generate(fixture) {
  const occurrence = fixture.occurrence ?? [];
  const horizon = fixture.horizon ?? [];
  const total = occurrence.length + horizon.length;

  const lines = [];
  lines.push(
    '-- GENERATED by scripts/gen-recurring-mirror-test.mjs from supabase/tests/fixtures/recurring-schedule-cases.json.'
  );
  lines.push('-- Do not edit by hand. Mirrors src/engine/recurring (D-04).');
  lines.push('');
  lines.push('begin;');
  lines.push('create extension if not exists pgtap with schema extensions;');
  lines.push('');
  lines.push(`select extensions.plan(${total});`);
  lines.push('');

  for (const c of occurrence) {
    lines.push(
      `select extensions.is(public.recurring_occurrence_date(${sqlLiteral(c.anchor)}::date, ${sqlLiteral(c.freq)}, ${c.n}), ${sqlLiteral(c.expected)}::date, ${sqlLiteral(`${c.freq} n=${c.n} from ${c.anchor}`)});`
    );
  }

  for (const c of horizon) {
    lines.push(
      `select extensions.is(public.recurring_horizon(${sqlLiteral(c.today)}::date), ${sqlLiteral(c.expected)}::date, ${sqlLiteral(`horizon ${c.today}`)});`
    );
  }

  lines.push('');
  lines.push('select * from extensions.finish();');
  lines.push('rollback;');
  lines.push('');

  // Normalise line endings to \n regardless of platform.
  return lines.join('\n').replace(/\r\n/g, '\n');
}

function main() {
  const checkMode = process.argv.includes('--check');
  const fixtureRaw = readFileSync(FIXTURE_PATH, 'utf8');
  const fixture = JSON.parse(fixtureRaw);
  const generated = generate(fixture);

  if (checkMode) {
    if (!existsSync(OUTPUT_PATH)) {
      console.error(`gen-recurring-mirror-test --check: ${OUTPUT_PATH} does not exist. Run without --check first.`);
      process.exit(1);
    }
    const onDisk = readFileSync(OUTPUT_PATH, 'utf8').replace(/\r\n/g, '\n');
    if (onDisk !== generated) {
      console.error(
        'gen-recurring-mirror-test --check: 27_recurring_schedule_mirror.test.sql is out of date with recurring-schedule-cases.json.\n' +
          'Run `node scripts/gen-recurring-mirror-test.mjs` and commit the result.'
      );
      process.exit(1);
    }
    console.log('gen-recurring-mirror-test --check: up to date.');
    process.exit(0);
  }

  writeFileSync(OUTPUT_PATH, generated);
  console.log(`Wrote ${OUTPUT_PATH}`);
}

main();
